using System;
class PassengerBehaviorTests {
 static int n;
 static void Check(bool ok,string message){n++;if(!ok){Console.WriteLine("FAIL "+message);Environment.Exit(1);}}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Check(rejected,name);}
 static void Main(){
  Check(typeof(PassengerBehaviorState).GetMethod("BindEffectTrip")!=null,"dirt effects need actual trip identity, separate from candidate draw");
  Check(typeof(PassengerBehaviorState).GetMethod("SetRepresentativeContext")!=null,"dialogue must track actual representative request outcome");
  foreach(PassengerType t in Enum.GetValues(typeof(PassengerType))){var p=PassengerBehaviorState.Create("stable",t);p.Validate();var q=p.Copy();Check(p.Variant==q.Variant&&p.Dialogue==q.Dialogue,"stable variant "+t);if(t!=PassengerType.General){Check(p.Choices.Length>=2&&!p.Respond(0,false),"safe response "+t);Check(p.Respond(0,true)&&!p.Respond(0,true),"one response "+t);Check(p.Dialogue.Length>0,"response memory "+t);} }
  var luggage=PassengerBehaviorState.Create("load",PassengerType.Luggage);Check(!luggage.BoardingReady&&!luggage.Board(),"load before boarding");luggage.Respond(0,true);luggage.Advance(10,false,true,0,100);Check(!luggage.BoardingReady,"moving load prohibited");luggage.Advance(10,true,false,0,100,true);Check(!luggage.BoardingReady,"paused load prohibited");luggage.Advance(4,true,false,0,100);luggage=luggage.Copy();luggage.Advance(6,true,false,0,100);Check(luggage.Board(),"load resumes remaining6");Check(luggage.Arrive()&&!luggage.Arrive()&&!luggage.Finish(true),"arrival locks once and unload required");luggage.Advance(10,true,false,1,100);Check(luggage.Finish(true),"unload complete");
  for(int i=0;i<100;i++){var food=PassengerBehaviorState.Create("food"+i,PassengerType.Food);food.Board();food.Advance(30,true,false,.7f,100);Check(food.DirtEvents.Length==0,"no automatic consent");food.Respond(1,true);food.Advance(20,false,true,.6f,100);Check(food.ConsumptionOccurred&&food.DirtEvents.Length==(food.SpillPlanned?2:1),"actual crumbs plus seeded spill");var care=new VehicleCare();foreach(var e in food.DirtEvents)care.Soil(e.Id,e.Amount);care=VehicleCare.Restore(care.Snapshot());foreach(var e in food.Copy().DirtEvents)care.Soil(e.Id,e.Amount);Check(care.Cleanliness==(food.SpillPlanned?92:98)&&!care.VomitUnwashed,"replay-safe food distinct vomit");}
  foreach(int choice in new[]{0,2}){var food=PassengerBehaviorState.Create("clean",PassengerType.Food);food.Board();food.Respond(choice,true);food.Advance(10,true,false,.2f,100);food.Advance(50,false,true,.8f,100);Check(food.DirtEvents.Length==0&&food.WorkRemaining==0,"sealed or cleanup clean");}
  var muddy=PassengerBehaviorState.Create("mud",PassengerType.MuddyLuggage);muddy.Respond(1,true);muddy.Board();Check(muddy.DirtEvents.Length==0,"mud only actual exit");muddy.Arrive();muddy.Finish(true);Check(muddy.DirtEvents.Length==1&&muddy.DirtEvents[0].Amount==5,"mud exit5");
  var shortSleep=PassengerBehaviorState.Create("short",PassengerType.Sleeping);shortSleep.Board();shortSleep.Advance(5,false,true,1,100);shortSleep.Arrive();shortSleep.Advance(60,true,false,1,100);Check(!shortSleep.Sleeping,"shorttrip never forced sleep");
  var sleepy=PassengerBehaviorState.Create("sleep",PassengerType.Sleeping);sleepy.Variant=0;sleepy.Board();sleepy.Advance(21,false,true,.4f,100);Check(sleepy.Sleeping,"actual journey sleep");var wake=DrunkRideState.Create("sleep",false);wake.NonDrunkSleep=true;wake.SleepPlanned=true;wake.Arrive(true);wake.Validate();wake.Advance(15,1);Check(wake.Disembark(true,true)&&!wake.IsDrunk,"non-drunk wake policy");
  var shallow=PassengerBehaviorState.Create("shallow",PassengerType.Sleeping);shallow.Variant=2;shallow.Respond(0,true);shallow.Board();shallow.Advance(25,false,true,.3f,100);shallow.Advance(20,false,true,.5f,100);shallow.Advance(1,true,false,.5f,100);Check(!shallow.Sleeping&&shallow.HasChoice,"shallow sleep wakes once at safe opportunity");Check(shallow.Respond(1,true)&&shallow.Sleeping&&!shallow.HasChoice,"shallow response resumes sleep remembers boundary");shallow.Validate();
  var frequency=new VehicleCare();for(int i=0;i<8;i++){var t=frequency.ReservePassenger("fixed",new PassengerType[0]);Check(t==frequency.ReservePassenger("changed",new[]{PassengerType.Food}),"reservation survives cancellation");frequency=VehicleCare.Restore(frequency.Snapshot());Check(frequency.CommitPassenger("trip"+i,t)&&!frequency.CommitPassenger("trip"+i,t),"consume only once");if(t!=PassengerType.General)Check(frequency.ReservePassenger("rest",new[]{PassengerType.Food})==PassengerType.General,"ordinary rest");}Check(frequency.Snapshot().encounterDrunks<=2,"daily cap2");
  var guarantee=new VehicleCare();var gs=guarantee.Snapshot();gs.encounterMisses=3;guarantee=VehicleCare.Restore(gs);Check(guarantee.ReservePassenger("guarantee",new PassengerType[0])==PassengerType.Drunk,"after3 guarantee");Check(guarantee.CommitPassenger("g",PassengerType.Drunk),"first drunk");guarantee.BeginDay(2);Check(guarantee.ReservePassenger("nextday",new PassengerType[0])==PassengerType.General,"rest carries day");
  var legacy=new VehicleCare();Check(legacy.BoardDrunk()&&!legacy.BoardDrunk(),"legacy cap1");Check(VehicleCare.Restore(new VehicleCareSnapshot()).Cleanliness==100,"old snapshot");Reject(()=>{var p=PassengerBehaviorState.Create("bad",PassengerType.Food);p.PreparationRemaining=float.NaN;p.Validate();},"malformed timer");Reject(()=>{var p=PassengerBehaviorState.Create("bad",PassengerType.Food);p.ConsumptionOccurred=true;p.Validate();},"unconsented dirt corrupt");Reject(()=>{var s=new VehicleCare().Snapshot();s.encounterDrunks=3;VehicleCare.Restore(s);},"invalid cap");
  Reject(()=>{var p=PassengerBehaviorState.Create("bad-work",PassengerType.General);p.PreparationRemaining=10;p.Validate();},"work cannot appear without choice");
  Reject(()=>{var p=PassengerBehaviorState.Create("bad-done",PassengerType.Luggage);p.Respond(0,true);p.PreparationRemaining=0;p.Board();p.Arrive();p.Settled=true;p.Validate();},"settled work cannot remain");
  var oldCare=VehicleCare.Restore(new VehicleCareSnapshot{drunksBoarded=1});Check(oldCare.Snapshot().encounterDrunks==1,"legacy drunk counts toward new daily cap");
  Reject(()=>{var s=new VehicleCare().Snapshot();s.soiled=null;VehicleCare.Restore(s);},"explicit new save requires soil identity list");
  var cancellation=PassengerBehaviorState.Create("cancel-mud",PassengerType.MuddyLuggage);cancellation.Respond(1,true);cancellation.Board();Check(cancellation.ExitCancelled()&&!cancellation.ExitCancelled()&&!cancellation.Arrived&&cancellation.DirtEvents.Length==1,"actual fatigue exit soils once without inventing arrival");cancellation.Validate();
  PassengerBehaviorState quietDrunk=null;for(int seed=0;seed<100;seed++){var candidate=PassengerBehaviorState.Create("quiet-drunk"+seed,PassengerType.Drunk);if(candidate.Variant==2){quietDrunk=candidate;break;}}Check(quietDrunk!=null&&quietDrunk.Quiet,"quiet drunk starts quiet before response");foreach(int response in new[]{0,1}){var q=quietDrunk.Copy();Check(q.Respond(response,true)&&q.Quiet,"either quiet drunk response preserves quiet");}
  var repeatedCare=new VehicleCare();string firstEffect=null;
  for(int trip=0;trip<2;trip++){var food=PassengerBehaviorState.Create("same-candidate",PassengerType.Food);food.BindEffectTrip("actual-trip-"+trip);food.Board();food.Respond(1,true);food.Advance(25,false,true,.6f,100);if(trip==0)firstEffect=food.DirtEvents[0].Id;else Check(firstEffect!=food.DirtEvents[0].Id,"same candidate different actual trip gets different soil event");foreach(var e in food.DirtEvents)repeatedCare.Soil(e.Id,e.Amount);int dirty=repeatedCare.Cleanliness;Check(dirty==(food.SpillPlanned?92:98),"each actual trip soils even after wash");foreach(var e in food.Copy().DirtEvents)repeatedCare.Soil(e.Id,e.Amount);Check(repeatedCare.Cleanliness==dirty,"same actual trip reload is idempotent");Reject(()=>food.BindEffectTrip("other-trip"),"effect identity cannot rebind");repeatedCare.Wash();}
  var oldEffect=PassengerBehaviorState.Create("legacy-food",PassengerType.Food);oldEffect.Board();oldEffect.Respond(1,true);oldEffect.Advance(25,false,true,.6f,100);Check(oldEffect.Copy().DirtEvents[0].Id=="legacy-food:crumbs","legacy typed save keeps original soil identity");
  foreach(var type in new[]{PassengerType.Comfort,PassengerType.Hurried,PassengerType.RouteChecking,PassengerType.Errand,PassengerType.PrecisionStop}){var p=PassengerBehaviorState.Create("representative",type);p.Respond(0,true);p.Board();p.Advance(35,false,true,.5f,100);p.SetRepresentativeContext(PassengerRepresentativeStatus.NotPresented,"");string unseen=p.Dialogue;Check(unseen.Contains("따로 정하지"),"type answer cannot invent representative agreement "+type);p.SetRepresentativeContext(PassengerRepresentativeStatus.Accepted,"실제 선택한 요청 안내");string accepted=p.Dialogue;Check(accepted.Contains("실제 선택한 요청 안내")&&accepted!=unseen,"followup remembers actual request response "+type);p.SetRepresentativeContext(PassengerRepresentativeStatus.Deferred,"안전상 보류");Check(p.Dialogue.Contains("보류")&&p.Dialogue!=accepted,"deferred request yields truthful different followup "+type);p.Arrive();p.SetRepresentativeContext(PassengerRepresentativeStatus.Succeeded,"달성");string success=p.CompletionReaction;p.SetRepresentativeContext(PassengerRepresentativeStatus.Failed,"미달");Check(success!=p.CompletionReaction,"actual completion result changes reaction "+type);p.SetRepresentativeContext(PassengerRepresentativeStatus.Neutral,"판정 불가");Check(p.Copy().CompletionReaction.Contains("추가 평가 없이")&&p.Copy().RepresentativeResponse=="판정 불가","neutral outcome context persists "+type);p.Validate();}
  Console.WriteLine("PASS PassengerBehaviorTests "+n);
 }
}
